<?php
require_once __DIR__ . '/../../bootstrap.php';
requireAdmin();
require_once __DIR__ . '/../../helpers/stifin-promoters.php';
header('Cache-Control: no-store');
$pageTitle = $topbarTitle = 'Laporan Cabang';
$branch = stifinPromoterBranchCode();
$month = is_string($_GET['month'] ?? null) ? $_GET['month'] : date('Y-m');
$start = DateTimeImmutable::createFromFormat('!Y-m', $month);
if (!$start || $start->format('Y-m') !== $month) { $start = new DateTimeImmutable('first day of this month midnight'); $month = $start->format('Y-m'); }
$range = [$start->format('Y-m-d'),$start->modify('+1 month')->format('Y-m-d')];
$day = is_string($_GET['day'] ?? null) ? $_GET['day'] : '';
$dayDate = DateTimeImmutable::createFromFormat('!Y-m-d',$day);
if ($dayDate && $dayDate->format('Y-m-d') === $day) { $range = [$day,$dayDate->modify('+1 day')->format('Y-m-d')]; } else { $day = ''; }
$perPromoter = $voucherRows = null;
try { if ($branch !== '') { $q=getDB()->prepare('SELECT promoter_code,status,COUNT(*) AS total FROM stifin_test_registrations WHERE branch_code=? AND created_at>=? AND created_at<? GROUP BY promoter_code,status ORDER BY promoter_code,status'); $q->execute([$branch,...$range]); $perPromoter=$q->fetchAll(); } } catch (Throwable $e) { error_log('STIFIn report unavailable'); }
try { if ($branch !== '' && stifinVoucherTransferSchema(getDB())) { $q=getDB()->prepare("SELECT o.order_number,q.transfer_promoter,q.quantity,q.transfer_status,q.transfer_checked_at FROM stifin_voucher_queue q JOIN orders o ON o.id=q.order_id AND o.user_id=q.user_id WHERE q.transfer_branch=? AND o.status='paid' AND o.paid_at>=? AND o.paid_at<? ORDER BY q.id DESC LIMIT 500"); $q->execute([$branch,...$range]); $voucherRows=$q->fetchAll(); } } catch (Throwable $e) { error_log('STIFIn voucher report unavailable'); }
$participants = $orders = null;
try { if ($branch !== '') { $q = getDB()->prepare('SELECT status,COUNT(*) AS total FROM stifin_test_registrations WHERE branch_code=? AND created_at>=? AND created_at<? GROUP BY status'); $q->execute([$branch,...$range]); $participants = $q->fetchAll(); } } catch (Throwable $e) { error_log('STIFIn participant report unavailable'); }
try { $q=getDB()->prepare("SELECT COUNT(*) AS total,COALESCE(SUM(total),0) AS revenue FROM orders WHERE status='paid' AND paid_at>=? AND paid_at<?"); $q->execute($range); $orders=$q->fetch(); } catch (Throwable $e) { error_log('STIFIn order report unavailable'); }
$states = ['registered'=>'Terdaftar','scheduled'=>'Terjadwal','completed'=>'Selesai','cancelled'=>'Dibatalkan'];
include __DIR__ . '/../../partials/head.php';
?>
<body class="bg-gray-50 dark:bg-gray-950 antialiased"><div class="flex h-screen overflow-hidden"><?php include __DIR__ . '/../../partials/sidebar-admin.php'; ?><div class="flex-1 flex flex-col overflow-hidden lg:ml-60"><?php include __DIR__ . '/../../partials/topbar.php'; ?><main class="flex-1 overflow-y-auto p-5 lg:p-6 space-y-4"><h1 class="text-2xl font-bold">Laporan Cabang</h1><form method="get" class="flex flex-wrap items-end gap-3"><label>Bulan<input type="month" name="month" value="<?= e($month) ?>" class="block border rounded p-2 dark:bg-gray-950"></label><label>Tanggal (opsional, mengutamakan tanggal)<input type="date" name="day" value="<?= e($day) ?>" class="block border rounded p-2 dark:bg-gray-950"></label><button class="border rounded p-2">Tampilkan</button><button type="button" class="border rounded p-2" onclick="window.print()">Cetak / PDF</button></form>
<section class="rounded-xl border p-5 bg-white dark:bg-gray-900"><h2 class="font-bold">Data resmi App Cabang</h2><p>Lihat hasil tes, rekap, dan transaksi voucher yang diimpor admin.</p><a class="underline" href="<?= e(APP_URL) ?>/admin/data-resmi-cabang">Buka data resmi App Cabang</a></section>
<section class="rounded-xl border p-5 bg-white dark:bg-gray-900"><h2 class="font-bold">Rekap peserta lokal per promotor</h2><?php if ($perPromoter === null): ?><p>Data belum tersedia.</p><?php elseif (!$perPromoter): ?><p>Belum ada pendaftaran dalam periode ini.</p><?php else: ?><table class="w-full text-left"><thead><tr><th>Promotor</th><th>Status</th><th>Jumlah</th></tr></thead><tbody><?php foreach ($perPromoter as $r): ?><tr class="border-t"><td><?= e($r['promoter_code']) ?></td><td><?= e($states[$r['status']] ?? '—') ?></td><td><?= (int)$r['total'] ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section>
<section class="rounded-xl border p-5 bg-white dark:bg-gray-900 overflow-x-auto"><h2 class="font-bold">Riwayat transfer voucher STIFIn Mulia</h2><p class="text-sm">Berdasarkan tanggal invoice lunas, bukan seluruh mutasi di pusat. Maksimal 500 catatan.</p><?php if ($voucherRows === null): ?><p>Data belum tersedia.</p><?php elseif (!$voucherRows): ?><p>Belum ada transfer dalam periode ini.</p><?php else: ?><table class="w-full text-left"><thead><tr><th>Invoice</th><th>Promotor</th><th>Jumlah</th><th>Status</th><th>Terakhir diperiksa</th></tr></thead><tbody><?php foreach ($voucherRows as $r): ?><tr class="border-t"><td><?= e($r['order_number']) ?></td><td><?= e($r['transfer_promoter'] ?? '—') ?></td><td><?= (int)$r['quantity'] ?></td><td><?= e(['pending'=>'Menunggu','review'=>'Perlu diperiksa','sent'=>'Terkirim'][$r['transfer_status']] ?? '—') ?></td><td><?= e($r['transfer_checked_at'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section>
<section class="rounded-xl border p-5 bg-white dark:bg-gray-900"><h2 class="font-bold">Pendaftaran peserta lokal · <?= e($branch ?: 'Belum dikonfigurasi') ?></h2><?php if ($participants === null): ?><p>Data belum tersedia.</p><?php else: $counts=array_column($participants,'total','status'); ?><div class="grid grid-cols-2 gap-3 mt-3"><?php foreach ($states as $key=>$label): ?><div class="border rounded p-3"><p><?= e($label) ?></p><strong><?= (int)($counts[$key] ?? 0) ?></strong></div><?php endforeach; ?></div><?php endif; ?></section>
<section class="rounded-xl border p-5 bg-white dark:bg-gray-900"><h2 class="font-bold">Pembayaran lunas STIFIn Mulia (semua produk)</h2><?php if ($orders): ?><p><?= (int)$orders['total'] ?> pembayaran · Rp<?= number_format((float)$orders['revenue'],0,',','.') ?></p><?php else: ?><p>Data belum tersedia.</p><?php endif; ?><p class="text-sm">Berdasarkan tanggal lunas; bukan saldo bank atau laporan pusat.</p><a class="underline" href="<?= e(APP_URL) ?>/admin/transactions">Detail transaksi</a></section></main></div></div><?php include __DIR__ . '/../../partials/footer.php'; ?>
